import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, useLocation } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { Header } from './components/Header';
import { BottomNav } from './components/BottomNav';
import Footer from './components/Footer';
import HomePage from './pages/HomePage';
import AdminPage from './pages/AdminPage';
import LoginPage from './pages/LoginPage';
import EmbedResourcePage from './pages/EmbedResourcePage';
import ProtectedRoute from './components/ProtectedRoute';
import PrivacyPolicyPage from './pages/PrivacyPolicyPage';
import { Resource, Lead } from './types';
import { auth } from './firebaseConfig';
import * as api from './services/api';

const AppContent: React.FC = () => {
  const [resources, setResources] = useState<Resource[]>([]);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const location = useLocation();

  // Check if we are in "headless" mode for embedding
  const isEmbedMode = location.pathname.startsWith('/embed/');

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setIsAuthenticated(!!user);
      setIsAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    const [fetchedResources, fetchedLeads] = await Promise.all([
      api.getResources(),
      isAuthenticated ? api.getLeads() : Promise.resolve([]),
    ]);
    setResources(fetchedResources);
    setLeads(fetchedLeads);
    setIsLoading(false);
  }, [isAuthenticated]);

  useEffect(() => {
    if (!isAuthLoading) {
      fetchData();
    }
  }, [fetchData, isAuthLoading]);

  useEffect(() => {
    if (window.self === window.top) return;

    let rafId: number;
    const postHeight = () => {
      rafId = requestAnimationFrame(() => {
        const height = document.documentElement.scrollHeight;
        window.parent.postMessage({ type: 'financial-library-resize', height }, '*');
      });
    };

    const observer = new ResizeObserver(postHeight);
    observer.observe(document.documentElement);
    document.addEventListener('transitionend', postHeight);

    postHeight();

    return () => {
      if (rafId) cancelAnimationFrame(rafId);
      observer.disconnect();
      document.removeEventListener('transitionend', postHeight);
    };
  }, []);

  const handleLogin = async (email: string, pass: string): Promise<boolean> => {
    return await api.login(email, pass);
  };

  const handleLogout = async () => {
    await api.logout();
  };

  const handleUpdateCredentials = async (currentPass: string, newUser: string, newPass: string): Promise<boolean> => {
    return await api.updateCredentials(currentPass, newUser, newPass);
  };

  const addLeadAndDownload = async (resourceId: string, leadData: { firstName: string; email: string; hasConsented: boolean; }) => {
    const resource = resources.find(r => r.id === resourceId);
    if (!resource) return;

    await api.addLead(resourceId, resource.title, leadData);

    if (!resource.isComingSoon && resource.fileUrl) {
      const link = document.createElement('a');
      link.href = resource.fileUrl;
      link.target = '_blank';
      link.download = resource.fileName || 'download';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }

    fetchData();
  };

  const handleGoogleDriveClick = async (resourceId: string) => {
    await api.incrementResourceAccessCount(resourceId);
    fetchData();
  };

  const addResource = async (resourceData: Omit<Resource, 'id' | 'downloadCount'>, file?: File) => {
    await api.addResource(resourceData, file);
    fetchData();
  };

  const updateResource = async (updatedResource: Resource, file?: File) => {
    await api.updateResource(updatedResource, file);
    fetchData();
  };

  const deleteResource = async (id: string) => {
    const resourceToDelete = resources.find(r => r.id === id);
    if (resourceToDelete) {
      await api.deleteResource(id, resourceToDelete);
      fetchData();
    }
  };

  if (isLoading || isAuthLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-xl font-semibold text-slate">Loading...</div>
      </div>
    );
  }

  return (
    <div className={`flex flex-col ${isEmbedMode ? 'bg-transparent' : 'min-h-screen bg-background-light'}`}>
      {!isEmbedMode && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}

      <main className={`flex-grow ${!isEmbedMode ? 'pb-16 md:pb-0' : ''}`}>
        <Routes>
          <Route path="/" element={<HomePage resources={resources} onDownload={addLeadAndDownload} onGoogleDriveClick={handleGoogleDriveClick} />} />
          <Route path="/embed/:id" element={<EmbedResourcePage resources={resources} onDownload={addLeadAndDownload} onGoogleDriveClick={handleGoogleDriveClick} />} />
          <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
          <Route path="/privacy" element={<PrivacyPolicyPage />} />
          <Route 
            path="/admin"
            element={
              <ProtectedRoute isAuthenticated={isAuthenticated}>
                <AdminPage 
                  resources={resources} 
                  leads={leads}
                  addResource={addResource}
                  updateResource={updateResource}
                  deleteResource={deleteResource}
                  adminUsername={currentUser?.email || 'Admin'}
                  updateCredentials={handleUpdateCredentials}
                />
              </ProtectedRoute>
            }
          />
        </Routes>
      </main>

      {!isEmbedMode && <Footer isAuthenticated={isAuthenticated} />}
      {!isEmbedMode && <BottomNav isAuthenticated={isAuthenticated} onLogout={handleLogout} />}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React from 'react';
import { useParams, Navigate } from 'react-router-dom';
import { Resource, ResourceType } from '../types';
import { DownloadIcon, LinkIcon, PdfIcon, SpreadsheetIcon, DocumentIcon, PresentationIcon, ImageIcon, VideoIcon, AudioIcon } from '../components/icons';

interface EmbedResourcePageProps {
  resources: Resource[];
  onDownload: (resourceId: string, lead: { firstName: string; email: string; hasConsented: boolean; }) => Promise<void>;
  onGoogleDriveClick: (resourceId: string) => void;
}

const EmbedResourcePage: React.FC<EmbedResourcePageProps> = ({ resources, onDownload, onGoogleDriveClick }) => {
  const { id } = useParams<{ id: string }>();
  const resource = resources.find(r => r.id === id);

  if (!resource) return <Navigate to="/" />;

  const handleAction = async () => {
    const lead = { firstName: 'Embed User', email: 'embed@user.com', hasConsented: true };
    await onDownload(resource.id, lead);
  };

  const getTypeIcon = () => {
    switch (resource.type) {
      case ResourceType.PDF: return <PdfIcon />;
      case ResourceType.SPREADSHEET: return <SpreadsheetIcon />;
      case ResourceType.DOCUMENT: return <DocumentIcon />;
      case ResourceType.PRESENTATION: return <PresentationIcon />;
      case ResourceType.IMAGE: return <ImageIcon />;
      case ResourceType.VIDEO: return <VideoIcon />;
      case ResourceType.AUDIO: return <AudioIcon />;
      default: return null;
    }
  };

  return (
    <div className="bg-white p-4 sm:p-6 border rounded-xl shadow-sm max-w-2xl mx-auto overflow-hidden">
      <div className="flex flex-col md:flex-row gap-6">
        <div className="w-full md:w-1/3 relative">
          <img 
            src={resource.imageUrl} 
            alt={resource.title} 
            className="w-full aspect-square object-cover rounded-lg shadow-sm"
          />
          {resource.isComingSoon && (
            <div className="absolute top-2 left-2 bg-yellow-400 text-yellow-900 text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded shadow-sm z-10">
              Coming Soon
            </div>
          )}
          <div className="absolute bottom-2 right-2 bg-primary/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-md shadow-lg z-10">
            {(resource.downloadCount || 0).toLocaleString()} {resource.isComingSoon ? 'SIGNUPS' : 'DOWNLOADS'}
          </div>
        </div>
        <div className="w-full md:w-2/3 flex flex-col justify-center">
          <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate/40 mb-1">
            {getTypeIcon()}
            <span>{resource.type} • {resource.category}</span>
          </div>
          <h2 className="text-2xl font-bold text-slate mb-2 leading-tight">{resource.title}</h2>
          <p className="text-gray-600 text-sm mb-6 leading-relaxed line-clamp-4">{resource.description}</p>

          <div className="flex flex-col gap-2">
            {resource.googleDriveUrl && (
              <a
                href={resource.googleDriveUrl}
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => onGoogleDriveClick(resource.id)}
                className="w-full text-center bg-white text-blue-600 px-4 py-2.5 rounded-lg shadow-sm flex items-center justify-center gap-2 transition-all duration-300 hover:bg-blue-50 border border-gray-200"
              >
                <LinkIcon className="w-4 h-4" />
                <span className="text-sm font-bold">Open in Google Drive</span>
              </a>
            )}
            <button
              onClick={handleAction}
              className="w-full text-center bg-primary text-white px-4 py-2.5 rounded-lg shadow-sm flex items-center justify-center gap-2 transition-all duration-300 hover:bg-primary-dark active:scale-[0.98]"
            >
              <DownloadIcon className="w-4 h-4" />
              <span className="text-sm font-bold">
                {resource.isComingSoon ? 'Notify Me of Release' : 'Download Now'}
              </span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default EmbedResourcePage;
